// The data should be freed with Free().
//
// Parameters:
//   - src: the IOStream to read all available data from.
//   - datasize: a pointer filled in with the number of bytes read, may be NULL.
//   - closeio: if true, calls CloseIO() on `src` before returning, even in the case of an error.
//
// Returns: the data or NULL on failure; call GetError() for more information.
//
// Thread safety: Do not use the same IOStream from two threads at once.
//
// Since: SDL 3.2.0.
//
// See also: LoadFile, SaveFile_IO
//
// The SDL allocation is copied into the returned slice and released. A nil result means SDL reported failure (see GetError); a non-nil empty slice means success with no items.
func LoadFile_IO(src *IOStream, closeio bool) []byte {
	var n uint
	p := fnLoadFile_IO(src, &n, closeio)
	return copyFreeBytes(p, int(n))
}

var fnLoadFile func(file *byte, datasize *uint) unsafe.Pointer

// Load all the data from a file path.
//
// The data is allocated with a zero byte at the end (null terminated) for
// convenience. This extra byte is not included in the value reported via
// `datasize`.
