//   - dst: the stream to which data will be written.
//   - value: the data to be written, in native format.
//
// Returns: true on successful write or false on failure; call GetError() for more information.
//
// Thread safety: Do not use the same IOStream from two threads at once.
//
// Since: SDL 3.2.0.
func WriteU64BE(dst *IOStream, value uint64) bool {
	return fnWriteU64BE(dst, value)
}

var fnWriteS64BE func(dst *IOStream, value int64) bool

// Use this function to write 64 bits in native format to an IOStream as
// big-endian data.
//
// SDL byteswaps the data only if necessary, so the application always
// specifies native format, and the data written will be in big-endian format.
//
// Parameters:
//   - dst: the stream to which data will be written.
//   - value: the data to be written, in native format.
//
// Returns: true on successful write or false on failure; call GetError() for more information.
//
// Thread safety: Do not use the same IOStream from two threads at once.
//
// Since: SDL 3.2.0.
func WriteS64BE(dst *IOStream, value int64) bool {
	return fnWriteS64BE(dst, value)
}
